with unpivoted as (select id, device_code, measure, val from (select id, device_code, humidity, temp_c, pressure from device_readings) src unpivot (val for measure in (humidity, temp_c, pressure)) unp) select measure, case when val >= 71 then 'PREMIUM' else 'STANDARD' end as val_tier, device_code, approx_percentile(val, 0.95) as val_p95, percentile_approx(val, array(0.25, 0.5, 0.75)) as val_quartiles, sum(val) as total_val, percentile_approx(val, array(0.25, 0.5, 0.75)) as val_quartiles_2, count(*) as cnt, grouping(measure) as gid from unpivoted group by rollup (measure, case when val >= 71 then 'PREMIUM' else 'STANDARD' end, device_code) order by device_code desc nulls last
